# Writes .env.local-solana snippets and prints docker compose command.
$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..\..")
$out = Join-Path $repoRoot ".env.local-solana"

@"
# Local solana-test-validator (generated by scripts/solana-local/apply-docker-local-rpc.ps1)
# Browser + Phantom use host loopback; control-api in Docker uses host.docker.internal.

SOLANA_RPC_ENDPOINT=http://host.docker.internal:8899
SOLANA_RPC_ENDPOINTS=http://host.docker.internal:8899
SOLANA_WS_ENDPOINT=ws://host.docker.internal:8900
SOLANA_NETWORK=devnet

NEXT_PUBLIC_SOLANA_RPC=http://127.0.0.1:8899
NEXT_PUBLIC_SOLANA_NETWORK=devnet
"@ | Set-Content -Path $out -Encoding utf8

Write-Host "Wrote $out"
Write-Host ""
Write-Host "Merge into your workflow:"
Write-Host "  1. Terminal A: pwsh -File scripts/solana-local/start-validator.ps1"
Write-Host "  2. Terminal B: pwsh -File scripts/solana-local/fund-oracle.ps1"
Write-Host "  3. Restart stack with local RPC:"
Write-Host "     docker compose -f docker-compose.dev.yml --env-file .env --env-file .env.local-solana up -d control-api web"
Write-Host ""
Write-Host "Phantom: Settings -> Developer -> Change network -> Custom RPC URL -> http://127.0.0.1:8899"
